(4346980, 627356, 74533, '<td valign="top">Interesting take  on the challenge.  The lashes are definately the subject.  The trouble is that the eyes usually are so it is difficult to not say that the eye needs to be more focused.</td>', 'Interesting take  on the challenge.  The lashes are definately the subject.  The trouble is that the eyes usually are so it is difficult to not say that the eye needs to be more focused.', '2007-12-31 06:58:19.000000', NULL, 1),
(4346982, 627491, 74533, '<td valign="top">Nice shot and interesting angle.  I cant really pick out a specific subject in an overall well composed shot.</td>', 'Nice shot and interesting angle.  I cant really pick out a specific subject in an overall well composed shot.', '2007-12-31 06:59:44.000000', NULL, 1),
