(4347456, 625553, 24454, '<td valign="top">This is awesome!  So clean.  So fresh.  So beautifully composed and artful.</td>', 'This is awesome!  So clean.  So fresh.  So beautifully composed and artful.', '2007-12-31 10:44:25.000000', NULL, 1),
(4347457, 627032, 68035, '<td valign="top">Fantastic image that really hits ALL the ket elements of the challenge.  I love the duetone and overall the composition feels like a pointilist work by Georges Seurat.  Superb composition.  Bump to 9</td>', 'Fantastic image that really hits ALL the ket elements of the challenge.  I love the duetone and overall the composition feels like a pointilist work by Georges Seurat.  Superb composition.  Bump to 9', '2007-12-31 10:45:19.000000', NULL, 1),
(4347458, 627504, 83600, '<td valign="top">Great looking stone- &amp; shot I might add. Good luck</td>', 'Great looking stone- & shot I might add. Good luck', '2007-12-31 10:45:40.000000', NULL, 1),
(4347459, 627402, 68035, '<td valign="top">Yep OK so its a staged shot, but none the worse for it.  Super composition and application of the rule of thirds and wonderful colours and sharpness</td>', 'Yep OK so its a staged shot, but none the worse for it.  Super composition and application of the rule of thirds and wonderful colours and sharpness', '2007-12-31 10:46:22.000000', NULL, 1),
(4347460, 627298, 68035, '<td valign="top">A magnificent shot of a magnificent animal.  Stunning sharpness and composition</td>', 'A magnificent shot of a magnificent animal.  Stunning sharpness and composition', '2007-12-31 10:47:14.000000', NULL, 1),
(4347461, 626541, 83600, '<td valign="top">I really hope you Ribbbon. Full on 10! Stunning</td>', 'I really hope you Ribbbon. Full on 10! Stunning', '2007-12-31 10:49:03.000000', NULL, 1),
(4347463, 625553, 68035, '<td valign="top">OK I have to admit to being somehwat confused by the sheer volume of eggs in this challenge, but I can say that IMO this stands head and shoulders above the other egg entries in the challenge.  I love the symettry of the pins and the colour of their heads provides a wonderful contrast against the rest of the high key nature of the shot.  This has the feel of a ribbon wonner about it.  Good luck</td>', 'OK I have to admit to being somehwat confused by the sheer volume of eggs in this challenge, but I can say that IMO this stands head and shoulders above the other egg entries in the challenge.  I love the symettry of the pins and the colour of their heads provides a wonderful contrast against the rest of the high key nature of the shot.  This has the feel of a ribbon wonner about it.  Good luck', '2007-12-31 10:49:17.000000', NULL, 1),
(4347464, 627054, 43774, '<td valign="top">This is simply beautiful!! I''ve never seen those flowers in real life before, I must look and see if any flower shop around here sells them, they are gorgeous and I want to photograph some.</td>', 'This is simply beautiful!! I''ve never seen those flowers in real life before, I must look and see if any flower shop around here sells them, they are gorgeous and I want to photograph some.', '2007-12-31 10:49:24.000000', NULL, 1),
(4347469, 627221, 43774, '<td valign="top">It looks alien....good job.</td>', 'It looks alien....good job.', '2007-12-31 10:50:06.000000', NULL, 1),
(4347470, 627375, 24454, '<td valign="top">Oh, I love this one.   What a cute face! :)</td>', 'Oh, I love this one.   What a cute face! :)', '2007-12-31 10:50:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4347471, 627547, 43774, '<td valign="top">This is a beautiful scene</td>', 'This is a beautiful scene', '2007-12-31 10:50:28.000000', NULL, 1),
(4347473, 626723, 68035, '<td valign="top">Quite a few people appear to have gone for the lone fisherman angle in this challenge, but this is a great example which helps lift it above the crowd.  Beautiful composition and colouring and the ''silky'' water in the foreground is a wonderful touch <br/> <br/>Sheer brilliance</td>', 'Quite a few people appear to have gone for the lone fisherman angle in this challenge, but this is a great example which helps lift it above the crowd.  Beautiful composition and colouring and the ''silky'' water in the foreground is a wonderful touch  Sheer brilliance', '2007-12-31 10:51:25.000000', NULL, 1),
(4347474, 626541, 43774, '<td valign="top">Stunning!</td>', 'Stunning!', '2007-12-31 10:51:39.000000', NULL, 1),
(4347476, 627079, 43774, '<td valign="top">Good job on the lighting, I just wish the cat were more in focus.</td>', 'Good job on the lighting, I just wish the cat were more in focus.', '2007-12-31 10:52:17.000000', NULL, 1),
(4347479, 627221, 68035, '<td valign="top">Wow!!!!!  A photograph that both fills me with awe and a touch of jealousy (we have cranes near my home...why didn''t I think of this).  A shot that has masses of power about it.  Beautifully composed and PP''s to maximise the images many strong points<br/> <br/>Simple yet majestic<br/> <br/>Great job</td>', 'Wow!!!!!  A photograph that both fills me with awe and a touch of jealousy (we have cranes near my home...why didn''t I think of this).  A shot that has masses of power about it.  Beautifully composed and PP''s to maximise the images many strong points Simple yet majestic Great job', '2007-12-31 10:53:23.000000', NULL, 1),
(4347485, 627057, 70181, '<td valign="top">Very dreamy.  You captured the motion perfectly.  Beautiful shot.</td>', 'Very dreamy.  You captured the motion perfectly.  Beautiful shot.', '2007-12-31 10:56:48.000000', NULL, 1),
(4347487, 626848, 54645, '<td valign="top">I like this. This is a great still life.</td>', 'I like this. This is a great still life.', '2007-12-31 10:57:21.000000', NULL, 1),
(4347490, 625684, 54645, '<td valign="top">Very cold, lovely view.</td>', 'Very cold, lovely view.', '2007-12-31 10:58:49.000000', NULL, 1),
(4347491, 626523, 54645, '<td valign="top">Interesting shot.</td>', 'Interesting shot.', '2007-12-31 10:59:22.000000', NULL, 1),
(4347493, 625553, 43774, '<td valign="top">Very cute</td>', 'Very cute', '2007-12-31 11:00:12.000000', NULL, 1),
