(4347504, 627054, 54645, '<td valign="top">Great composition. I really this.</td>', 'Great composition. I really this.', '2007-12-31 11:02:57.000000', NULL, 1),
(4347507, 627533, 54645, '<td valign="top">I like the lighting. Well done</td>', 'I like the lighting. Well done', '2007-12-31 11:04:08.000000', NULL, 1),
