(4348511, 627511, 79955, '<td valign="top">Recommend that you go for a vertical crop and leave out the reddish portion - would have been great - 5</td>', 'Recommend that you go for a vertical crop and leave out the reddish portion - would have been great - 5', '2007-12-31 19:50:21.000000', NULL, 1),
