(4349187, 626699, 83313, '<td valign="top">Great detail colors and perspective.</td>', 'Great detail colors and perspective.', '2008-01-01 03:42:07.000000', NULL, 1),
(4349192, 627391, 83313, '<td valign="top">The DOF limitations make the rock above water a little fuzzy. The near rock is clearly the subject, but my eye is divided between the two rocks. Otherwise, this is pretty good.</td>', 'The DOF limitations make the rock above water a little fuzzy. The near rock is clearly the subject, but my eye is divided between the two rocks. Otherwise, this is pretty good.', '2008-01-01 03:45:20.000000', NULL, 1),
