(4352836, 627013, 23458, '<td valign="top">The title of the challenge aside - the contrast here is a little excessive. Nice catch though.</td>', 'The title of the challenge aside - the contrast here is a little excessive. Nice catch though.', '2008-01-02 05:48:52.000000', NULL, 1),
(4352839, 627208, 23458, '<td valign="top">Nice, clean and crisp. I don''t know if this fits my conception of the challenge - but then again I really have no idea what the challenge is supposed to entail in this case. I think you could have cloned out the white speck on the top of the yolk, but otherwise this is a very professional shot. 7.</td>', 'Nice, clean and crisp. I don''t know if this fits my conception of the challenge - but then again I really have no idea what the challenge is supposed to entail in this case. I think you could have cloned out the white speck on the top of the yolk, but otherwise this is a very professional shot. 7.', '2008-01-02 05:51:26.000000', NULL, 1),
(4352840, 625277, 23458, '<td valign="top">Stunning scene. Nice use of black and white. Well composed. Understated and effective. <br/> <br/>Lame title. <br/> <br/>8 regardless. <br/> <br/>(on the downside - I''m not sure it''s as crisp as it could be around the top of the mountain on the left hand side).</td>', 'Stunning scene. Nice use of black and white. Well composed. Understated and effective.  Lame title.  8 regardless.  (on the downside - I''m not sure it''s as crisp as it could be around the top of the mountain on the left hand side).', '2008-01-02 05:53:44.000000', NULL, 1),
