(4362272, 627321, 50695, '<td valign="top">I just can''t get over those oofbirds. remarkable.</td>', 'I just can''t get over those oofbirds. remarkable.', '2008-01-05 00:28:39.000000', NULL, 1),
(4362273, 627112, 50695, '<td valign="top">Nice swooping composition.</td>', 'Nice swooping composition.', '2008-01-05 00:28:56.000000', NULL, 1),
