(4362277, 627332, 50695, '<td valign="top">you get a 7 for making my laugh.</td>', 'you get a 7 for making my laugh.', '2008-01-05 00:30:16.000000', NULL, 1),
(4362279, 626992, 50695, '<td valign="top">kind of a standard concept, but your execution is enthusiastic and interesting.</td>', 'kind of a standard concept, but your execution is enthusiastic and interesting.', '2008-01-05 00:31:13.000000', NULL, 1),
(4362281, 625352, 50695, '<td valign="top">This shot has that dpc stagedness that I''m not fond of, but the correlation of big umbrella to little umbrella is fascinating, the composition is just interesting enough, and since I am spared from looking into an insincere model''s eyes, I can be drawn into the fantasy (normally it is very difficult to relate to a beautiful model).</td>', 'This shot has that dpc stagedness that I''m not fond of, but the correlation of big umbrella to little umbrella is fascinating, the composition is just interesting enough, and since I am spared from looking into an insincere model''s eyes, I can be drawn into the fantasy (normally it is very difficult to relate to a beautiful model).', '2008-01-05 00:33:59.000000', NULL, 1),
(4362282, 627033, 50695, '<td valign="top">simple but effective. It''s like a beautiful sideways letter.</td>', 'simple but effective. It''s like a beautiful sideways letter.', '2008-01-05 00:34:21.000000', NULL, 1),
(4362283, 627330, 50695, '<td valign="top">I feel like high-contrast b/w corridor shots is becoming its own cliche around here, but this is certainly a very good example of the genre.</td>', 'I feel like high-contrast b/w corridor shots is becoming its own cliche around here, but this is certainly a very good example of the genre.', '2008-01-05 00:35:33.000000', NULL, 1),
(4362284, 625684, 50695, '<td valign="top">a lovely symphony of color variations from pane to pane.</td>', 'a lovely symphony of color variations from pane to pane.', '2008-01-05 00:35:52.000000', NULL, 1),
(4362286, 626199, 50695, '<td valign="top">the radiating branches add a lot of energy to this shot. well done.</td>', 'the radiating branches add a lot of energy to this shot. well done.', '2008-01-05 00:36:16.000000', NULL, 1),
(4362287, 626984, 50695, '<td valign="top">the quirky-but-still-balanced composition helps this.</td>', 'the quirky-but-still-balanced composition helps this.', '2008-01-05 00:36:49.000000', NULL, 1),
(4362288, 627495, 50695, '<td valign="top">wild processing. funky. I''ll give it a 7 for funk appeal.</td>', 'wild processing. funky. I''ll give it a 7 for funk appeal.', '2008-01-05 00:37:35.000000', NULL, 1),
(4362289, 627076, 50695, '<td valign="top">I enjoy the disorienting, energetic composition.</td>', 'I enjoy the disorienting, energetic composition.', '2008-01-05 00:37:56.000000', NULL, 1),
