(4362298, 627191, 50695, '<td valign="top">elegant. and the "missing" helmets are thought provoking (or story suggesting).</td>', 'elegant. and the "missing" helmets are thought provoking (or story suggesting).', '2008-01-05 00:41:47.000000', NULL, 1),
(4362299, 625845, 50695, '<td valign="top">energetic diagonal composition. The dark shapes of water on the bottom are crucial. Lovely blue and red tones complement each other well. Well done.</td>', 'energetic diagonal composition. The dark shapes of water on the bottom are crucial. Lovely blue and red tones complement each other well. Well done.', '2008-01-05 00:42:56.000000', NULL, 1),
(4362325, 625531, 80859, '<td valign="top">they''re adorable.  i wish the girl''s hand didn''t obstruct the child on the right''s face.  her dress being isolated by contrast is a good idea.  imo, though, there''s too much noise, especially in the face of the little boy on the left of the photo.</td>', 'they''re adorable.  i wish the girl''s hand didn''t obstruct the child on the right''s face.  her dress being isolated by contrast is a good idea.  imo, though, there''s too much noise, especially in the face of the little boy on the left of the photo.', '2008-01-05 00:58:14.000000', NULL, 1),
(4362338, 627057, 30982, '<td valign="top">Since he''s left, it can''t be xion, but it does remind me of him.  An incredible sense of freedom and light.</td>', 'Since he''s left, it can''t be xion, but it does remind me of him.  An incredible sense of freedom and light.', '2008-01-05 01:02:51.000000', NULL, 1),
(4362409, 626523, 30982, '<td valign="top">Excellent high contrast (or whatever) shot.  Like a painting and a photograph combined, only in black and white.</td>', 'Excellent high contrast (or whatever) shot.  Like a painting and a photograph combined, only in black and white.', '2008-01-05 01:41:36.000000', NULL, 1),
(4362412, 626971, 30982, '<td valign="top">Excellent entry for the challenge - I love the gentle tenderness of the reds.</td>', 'Excellent entry for the challenge - I love the gentle tenderness of the reds.', '2008-01-05 01:45:11.000000', NULL, 1),
(4362414, 626985, 30982, '<td valign="top">I like this alot.  Well seen and captured.</td>', 'I like this alot.  Well seen and captured.', '2008-01-05 01:45:22.000000', NULL, 1),
(4362415, 627330, 30982, '<td valign="top">Perfect in my book.  My personal favorite for this challenge.</td>', 'Perfect in my book.  My personal favorite for this challenge.', '2008-01-05 01:45:34.000000', NULL, 1),
(4362417, 627032, 30982, '<td valign="top">I love the natural grain of the snow!  Very nice shot - thanks for entering it!</td>', 'I love the natural grain of the snow!  Very nice shot - thanks for entering it!', '2008-01-05 01:45:49.000000', NULL, 1),
