(4362547, 627533, 23458, '<td valign="top">This is a pleasant enough image. Although it should be said that the lighting is somewhat flat. <br/> <br/>You''re obviously pretty handy with a camera - perhaps you could have demonstrated a little more originality in respect of the subject, the composition, or just the lighting.</td>', 'This is a pleasant enough image. Although it should be said that the lighting is somewhat flat.  You''re obviously pretty handy with a camera - perhaps you could have demonstrated a little more originality in respect of the subject, the composition, or just the lighting.', '2008-01-05 03:51:45.000000', NULL, 1),
(4362549, 627129, 23458, '<td valign="top">Stark. Almost austere. <br/> <br/>Wonderful though.</td>', 'Stark. Almost austere.  Wonderful though.', '2008-01-05 03:53:16.000000', NULL, 1),
(4362551, 627118, 23458, '<td valign="top">Great subject. Wonderful light. <br/> <br/>On a technical level I can''t help but feel that there''s a little too much foreground, but otherwise this is great. 8.</td>', 'Great subject. Wonderful light.  On a technical level I can''t help but feel that there''s a little too much foreground, but otherwise this is great. 8.', '2008-01-05 03:54:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4362554, 627279, 23458, '<td valign="top">Great catch. Pleasing composition. I can see a little haloing where you''ve darkened the background, but my monitor is currently too bright. Still - there is perhaps a little interest in the background - taking it out leaves a bit of an unnatural feel (though, will be rewarded by the voters no doubt). 7</td>', 'Great catch. Pleasing composition. I can see a little haloing where you''ve darkened the background, but my monitor is currently too bright. Still - there is perhaps a little interest in the background - taking it out leaves a bit of an unnatural feel (though, will be rewarded by the voters no doubt). 7', '2008-01-05 03:57:05.000000', NULL, 1),
(4362557, 627079, 23458, '<td valign="top">Lovely warm feel. Not a bad pet portrait at all.</td>', 'Lovely warm feel. Not a bad pet portrait at all.', '2008-01-05 03:57:58.000000', NULL, 1),
(4362559, 627255, 23458, '<td valign="top">Ahh... This is great. A mouth full of teeth? Or just breakfast?</td>', 'Ahh... This is great. A mouth full of teeth? Or just breakfast?', '2008-01-05 03:59:10.000000', NULL, 1),
