(4362579, 627491, 77192, '<td valign="top">Normally I like turning the camera slightly to add a fresh angle to a shot (no pun intended - well all right yes it was intended) but I don''t think it comes off quite in this case</td>', 'Normally I like turning the camera slightly to add a fresh angle to a shot (no pun intended - well all right yes it was intended) but I don''t think it comes off quite in this case', '2008-01-05 04:36:01.000000', NULL, 1),
(4362580, 627511, 16046, '<td valign="top">Don''t quite get what happened to her left eye, otherwise a nice image</td>', 'Don''t quite get what happened to her left eye, otherwise a nice image', '2008-01-05 04:36:21.000000', NULL, 1),
(4362584, 627032, 16046, '<td valign="top">Great image, super story telling here, super comp. 10</td>', 'Great image, super story telling here, super comp. 10', '2008-01-05 04:38:21.000000', NULL, 1),
(4362586, 626848, 16046, '<td valign="top">Awesome, you deserve the 10 I''m giving you</td>', 'Awesome, you deserve the 10 I''m giving you', '2008-01-05 04:39:02.000000', NULL, 1),
