(4362680, 627330, 67258, '<td valign="top">One of my favourite of the challenge, both as a photograph in its own right, and in terms of the challenge itself.  Excellent work.</td>', 'One of my favourite of the challenge, both as a photograph in its own right, and in terms of the challenge itself.  Excellent work.', '2008-01-05 07:34:52.000000', NULL, 1),
(4362697, 626824, 67258, '<td valign="top">Love the title!  A good study in contrast.</td>', 'Love the title!  A good study in contrast.', '2008-01-05 07:54:33.000000', NULL, 1),
(4362700, 627033, 67258, '<td valign="top">I really admire the simplicity of this.</td>', 'I really admire the simplicity of this.', '2008-01-05 07:54:58.000000', NULL, 1),
(4362705, 627545, 67258, '<td valign="top">Very pretty, and fits the challenge well.  I like the way there is both contast and continuity - contrast in terms of tones, but continuity with the lace effect of the skeletal leaf and the white lace curtains.</td>', 'Very pretty, and fits the challenge well.  I like the way there is both contast and continuity - contrast in terms of tones, but continuity with the lace effect of the skeletal leaf and the white lace curtains.', '2008-01-05 07:56:41.000000', NULL, 1),
(4362712, 627505, 67258, '<td valign="top">A sound composition with the curve leading the eye through the photo.  the old piece of farm machinery (a thresher?) contrasts well with the snow.</td>', 'A sound composition with the curve leading the eye through the photo.  the old piece of farm machinery (a thresher?) contrasts well with the snow.', '2008-01-05 07:58:47.000000', NULL, 1),
(4362731, 626541, 67258, '<td valign="top">What a superb photograph!  The detail and texture is incedible, and the mono conversion masterly - Excellent!</td>', 'What a superb photograph!  The detail and texture is incedible, and the mono conversion masterly - Excellent!', '2008-01-05 08:10:55.000000', NULL, 1),
