(4362739, 627057, 67258, '<td valign="top">This is impressive!  Two forms of contrast, too - the white gull against the darker background, and the contrasting diagonal lines.  The tilted composition adds a strong sense of dynamism.</td>', 'This is impressive!  Two forms of contrast, too - the white gull against the darker background, and the contrasting diagonal lines.  The tilted composition adds a strong sense of dynamism.', '2008-01-05 08:16:47.000000', NULL, 1),
(4362740, 626985, 67258, '<td valign="top">One of my favourites of the challenge.  There is a strong sense of narrative here, yet provided by relatively few elements.  I find the shadows quite ominoous - almost as though the second shadow is of a stalker; the peopleless scene adds to this feel.  Impressive.</td>', 'One of my favourites of the challenge.  There is a strong sense of narrative here, yet provided by relatively few elements.  I find the shadows quite ominoous - almost as though the second shadow is of a stalker; the peopleless scene adds to this feel.  Impressive.', '2008-01-05 08:19:07.000000', NULL, 1),
(4362951, 627308, 70449, '<td valign="top">i like the shot, however the tissue box and water bottle do not make very interesting subjects.</td>', 'i like the shot, however the tissue box and water bottle do not make very interesting subjects.', '2008-01-05 10:23:08.000000', NULL, 1),
(4363449, 627513, 66709, '<td valign="top">Is this red river beach</td>', 'Is this red river beach', '2008-01-05 13:48:48.000000', NULL, 1),
