(4367759, 625553, 29011, '<td valign="top">So wonderfully light , clever and witty :) Wonderful example of using color contrast to isoloate the object.<br/>Hope this does well. My pick for the top10 for sure. Good luck!</td>', 'So wonderfully light , clever and witty :) Wonderful example of using color contrast to isoloate the object.Hope this does well. My pick for the top10 for sure. Good luck!', '2008-01-06 22:48:19.000000', NULL, 1),
(4367762, 626541, 29011, '<td valign="top">Love the tones and composition of the shot. Like how you''ve burnt the bottom part of the shot, have mixed thoughts about the top right part though. But it comes together quite nicely. Top10 fave.</td>', 'Love the tones and composition of the shot. Like how you''ve burnt the bottom part of the shot, have mixed thoughts about the top right part though. But it comes together quite nicely. Top10 fave.', '2008-01-06 22:48:44.000000', NULL, 1),
