(4368313, 627151, 53814, '<td valign="top">wow</td>', 'wow', '2008-01-07 00:52:28.000000', NULL, 0),
(4368319, 626541, 15305, '<td valign="top">Wow Enzo, way to go!! Congratulations on a well deserved blue ribbon and a new personal best!!!</td>', 'Wow Enzo, way to go!! Congratulations on a well deserved blue ribbon and a new personal best!!!', '2008-01-07 00:54:06.000000', NULL, 0),
(4368323, 627118, 20168, '<td valign="top">Welcome back on the Top Ten Board Zoomy! Love this image, especially the old world feel of this fisherman in sihouette with the fabulous sun rays highlighting the glory days of commercial fishing! Love the B/W choice for this photo. Makes a photographer want to say "crespuscular, crespuscular, crespuscular!"</td>', 'Welcome back on the Top Ten Board Zoomy! Love this image, especially the old world feel of this fisherman in sihouette with the fabulous sun rays highlighting the glory days of commercial fishing! Love the B/W choice for this photo. Makes a photographer want to say "crespuscular, crespuscular, crespuscular!"', '2008-01-07 00:54:45.000000', NULL, 0),
(4368324, 626541, 17203, '<td valign="top">Excellent! The contrast, tones and slight sepia were perfect for this shot. Congrats on the personal best!</td>', 'Excellent! The contrast, tones and slight sepia were perfect for this shot. Congrats on the personal best!', '2008-01-07 00:54:50.000000', NULL, 0),
(4368328, 627319, 33068, '<td valign="top">WOW!  Brilliant use of light and exposure.  Stunning........</td>', 'WOW!  Brilliant use of light and exposure.  Stunning........', '2008-01-07 00:56:14.000000', NULL, 0),
(4368329, 627319, 30982, '<td valign="top">VERY cool technique!  Thanks for sharing how you did this!  And while it may be easy to duplicate in PS, I''m pretty sure it wouldn''t look as convincing.  Nice work all around.</td>', 'VERY cool technique!  Thanks for sharing how you did this!  And while it may be easy to duplicate in PS, I''m pretty sure it wouldn''t look as convincing.  Nice work all around.', '2008-01-07 00:56:23.000000', NULL, 0),
(4368332, 627097, 68504, '<td valign="top">Enjoyed it for sure.  A real BW gem.</td>', 'Enjoyed it for sure.  A real BW gem.', '2008-01-07 00:56:40.000000', NULL, 0),
