(4368431, 625835, 44058, '<td valign="top">thank you everyone for the comments on mum''s image. I enjoyed posing in this formation for the camera. Though I have to say, my muscles did hurt afterwards.</td>', 'thank you everyone for the comments on mum''s image. I enjoyed posing in this formation for the camera. Though I have to say, my muscles did hurt afterwards.', '2008-01-07 01:27:39.000000', NULL, 0),
(4368433, 626541, 72103, '<td valign="top">Beautiful image Enzo, and a beautiful spot, i''ve been there......  Congrats on a great start to the year, and thanx for your comments.....  Alan</td>', 'Beautiful image Enzo, and a beautiful spot, i''ve been there......  Congrats on a great start to the year, and thanx for your comments.....  Alan', '2008-01-07 01:28:00.000000', NULL, 0),
