(4368494, 625835, 18450, '<td valign="top">Congrats Judi!! Simply superb! Beautiful image and a gorgeous daughter.</td>', 'Congrats Judi!! Simply superb! Beautiful image and a gorgeous daughter.', '2008-01-07 02:04:19.000000', NULL, 0),
(4368495, 625835, 48228, '<td valign="top">Awesome pose and what a beautiful young daughter you have.....  <br/> <br/>I really love this portrait as it is so emotive and so strong in a gentle sort of way..... <br/> <br/>Well done to another one of my dear Aussie friends.....<br/>Also a wonderful portrait of one of our younger DPC members. Well done <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/31_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/31_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/31_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=44058" rel="nofollow" target="_blank">Kita</a>, You have an amazing Mother who take the most amazing photos that so deserve ribbons.....<br/></td>', 'Awesome pose and what a beautiful young daughter you have.....   I really love this portrait as it is so emotive and so strong in a gentle sort of way.....  Well done to another one of my dear Aussie friends.....Also a wonderful portrait of one of our younger DPC members. Well done  Kita, You have an amazing Mother who take the most amazing photos that so deserve ribbons.....', '2008-01-07 02:04:24.000000', NULL, 0),
(4368496, 626541, 42013, '<td valign="top">Special work Enzo. This is sublime. Faved for sure and congrats!</td>', 'Special work Enzo. This is sublime. Faved for sure and congrats!', '2008-01-07 02:04:41.000000', NULL, 0),
