(4371249, 626523, 35602, '<td valign="top">Congrats on your top 10.  did a nice job of making it feel ethereal, which adds to the sense of isolation of the two, as though there is nothing else in the world but the two of them.</td>', 'Congrats on your top 10.  did a nice job of making it feel ethereal, which adds to the sense of isolation of the two, as though there is nothing else in the world but the two of them.', '2008-01-07 19:09:59.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4371588, 625835, 19978, '<td valign="top">Judi, of all your shots I have enjoyed over the past few years, this one may be the most arresting. It''s such a perfectly executed shot, and technically perfect. One of the handful of shots, IMO, that takes DPC to a whole new level. Just amazing.</td>', 'Judi, of all your shots I have enjoyed over the past few years, this one may be the most arresting. It''s such a perfectly executed shot, and technically perfect. One of the handful of shots, IMO, that takes DPC to a whole new level. Just amazing.', '2008-01-07 19:59:31.000000', NULL, 0),
(4371599, 627426, 66384, '<td valign="top">Very interesting portrait. The girl seems troubled, shy, introspective. I don''t know if she is, but that''s what the image conveys to me, and that makes it interesting. I think the darkness adds to that feeling. So I disagree with the voters and commenters who don''t like the contrast or exposure.</td>', 'Very interesting portrait. The girl seems troubled, shy, introspective. I don''t know if she is, but that''s what the image conveys to me, and that makes it interesting. I think the darkness adds to that feeling. So I disagree with the voters and commenters who don''t like the contrast or exposure.', '2008-01-07 20:03:25.000000', NULL, 0),
(4371664, 626541, 38032, '<td valign="top">This is eye sushi<br/> <br/>delicious and wasabi <br/> <br/>leaves me euphoric</td>', 'This is eye sushi delicious and wasabi  leaves me euphoric', '2008-01-07 20:23:24.000000', NULL, 0),
