(4371934, 625835, 3214, '<td valign="top">Love how you used high key to isolate your fabulous subject, and the pose adds considerable interest.  Congrats on the high score, this certainly deserved it!</td>', 'Love how you used high key to isolate your fabulous subject, and the pose adds considerable interest.  Congrats on the high score, this certainly deserved it!', '2008-01-07 21:41:30.000000', NULL, 0),
(4371976, 627178, 44877, '<td valign="top">Simply stunning. You were robbed - but then many of us are often. Know that this is an outstanding image.</td>', 'Simply stunning. You were robbed - but then many of us are often. Know that this is an outstanding image.', '2008-01-07 21:48:33.000000', NULL, 0),
(4371983, 626985, 32997, '<td valign="top">brilliant amigo!</td>', 'brilliant amigo!', '2008-01-07 21:50:04.000000', NULL, 0),
(4372012, 626541, 62318, '<td valign="top">I loved the photo during the challenge (gave you a seven). It wasn''t my pick to win, mainly because I felt that the contrast portion had a lot to do with the post processing (dodge/burn). Still you can not deny the beauty of the photo. Incidentally I would have given it a higher rating in FS. <br/> <br/>Also, on a side note, I especially like  your first outtake, even more so than your entry.</td>', 'I loved the photo during the challenge (gave you a seven). It wasn''t my pick to win, mainly because I felt that the contrast portion had a lot to do with the post processing (dodge/burn). Still you can not deny the beauty of the photo. Incidentally I would have given it a higher rating in FS.  Also, on a side note, I especially like  your first outtake, even more so than your entry.', '2008-01-07 21:57:54.000000', NULL, 0),
(4372043, 627537, 61651, '<td valign="top">A truly gorgeous shot.  I like how you composed it.</td>', 'A truly gorgeous shot.  I like how you composed it.', '2008-01-07 22:03:35.000000', NULL, 0),
